/*
 * Real-artifact harness for MediaInfo.wdx (Linux).
 *
 * dlopen()s the actual built plugin and drives its WDX C ABI the way Double
 * Commander does — ContentGetSupportedField to map field indices, then
 * ContentGetValue / ContentGetValueW against files synthesized here with known
 * properties:
 *   - a 320x200 PNG at 300 dpi  (Qt image path)
 *   - a 320x200 JPEG            (Qt image path)
 *   - a 2-page PDF              (poppler path)
 *   - a 1.0s 8kHz mono WAV      (libavformat path)
 * plus AVI/MKV/MP4 clips generated by test/run.sh (ffmpeg) when present.
 *
 * Build:
 *   g++ -std=c++17 -o build/test_host test/test_host.cpp \
 *       $(pkg-config --cflags --libs Qt6Gui)
 * Run:
 *   ./build/test_host build/MediaInfo.wdx [dir-with-ffmpeg-samples]
 */

#define _GNU_SOURCE 1

#include <QColor>
#include <QCoreApplication>
#include <QFile>
#include <QImage>
#include <QString>
#include <QTemporaryDir>

#include <dlfcn.h>
#include <fenv.h>

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <thread>
#include <vector>

#define ft_numeric_32        1
#define ft_numeric_floating  3
#define ft_string            8
#define ft_nosuchfield      -1
#define ft_fieldempty       -3
#define ft_delayed           0
#define CONTENT_DELAYIFSLOW  1

using GetField_t = int (*)(int, char *, char *, int);
using GetValue_t = int (*)(char *, int, int, void *, int, int);
using GetValueW_t = int (*)(char16_t *, int, int, void *, int, int);
using GetDetect_t = int (*)(char *, int);

static GetField_t GetField;
static GetValue_t GetValue;
static GetValueW_t GetValueW;
static GetDetect_t GetDetect;
static std::vector<std::string> gNames; /* field index -> name */

static int gPass = 0, gFail = 0;
static void check(bool ok, const std::string &msg) {
    std::printf("  [%s] %s\n", ok ? "PASS" : "FAIL", msg.c_str());
    if (ok) ++gPass; else ++gFail;
}

static int idx(const std::string &name) {
    for (size_t i = 0; i < gNames.size(); ++i)
        if (gNames[i] == name) return int(i);
    return -1;
}

static int getInt(const std::string &path, const std::string &field) {
    int32_t out = INT32_MIN;
    int r = GetValue(const_cast<char *>(path.c_str()), idx(field), 0, &out, sizeof out, 0);
    return (r == ft_numeric_32) ? out : INT32_MIN;
}
static double getFloat(const std::string &path, const std::string &field) {
    double out = NAN;
    int r = GetValue(const_cast<char *>(path.c_str()), idx(field), 0, &out, sizeof out, 0);
    return (r == ft_numeric_floating) ? out : NAN;
}
static bool getStr(const std::string &path, const std::string &field, std::string &out) {
    char buf[1024] = {0};
    int r = GetValue(const_cast<char *>(path.c_str()), idx(field), 0, buf, sizeof buf, 0);
    if (r != ft_string) return false;
    out = buf;
    return true;
}

/* ---- sample synthesis --------------------------------------------------- */

static std::string saveImage(const QString &path, const char *format, int w, int h, int dpi) {
    QImage img(w, h, QImage::Format_RGB32);
    img.fill(QColor(40, 90, 180));
    if (dpi > 0) {
        img.setDotsPerMeterX(int(std::lround(dpi / 0.0254)));
        img.setDotsPerMeterY(int(std::lround(dpi / 0.0254)));
    }
    if (!img.save(path, format)) {
        std::fprintf(stderr, "cannot write %s\n", qPrintable(path));
        return std::string();
    }
    return path.toStdString();
}

/* Minimal, well-formed 2-page PDF (exact xref offsets). */
static std::string makePdf(const QString &path) {
    std::string out = "%PDF-1.4\n";
    std::vector<long> offs;
    auto add = [&](const std::string &body) {
        offs.push_back(long(out.size()));
        out += body;
    };
    add("1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");
    add("2 0 obj\n<< /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 >>\nendobj\n");
    add("3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 200] >>\nendobj\n");
    add("4 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 200] >>\nendobj\n");
    const long xref = long(out.size());
    char buf[256];
    out += "xref\n0 5\n0000000000 65535 f \n";
    for (long o : offs) {
        std::snprintf(buf, sizeof buf, "%010ld 00000 n \n", o);
        out += buf;
    }
    std::snprintf(buf, sizeof buf,
                  "trailer\n<< /Size 5 /Root 1 0 R >>\nstartxref\n%ld\n%%%%EOF\n", xref);
    out += buf;

    QFile f(path);
    if (!f.open(QIODevice::WriteOnly)) return std::string();
    f.write(out.data(), qint64(out.size()));
    f.close();
    return path.toStdString();
}

static void put32le(QByteArray &d, uint32_t v) {
    const char b[4] = {char(v), char(v >> 8), char(v >> 16), char(v >> 24)};
    d.append(b, 4);
}
static void put16le(QByteArray &d, uint16_t v) {
    const char b[2] = {char(v), char(v >> 8)};
    d.append(b, 2);
}

static std::string makeWav(const QString &path) {
    const uint32_t rate = 8000, channels = 1, bps = 16, frames = 8000;
    const uint32_t dataSize = frames * channels * (bps / 8);
    QByteArray d;
    d.append("RIFF", 4); put32le(d, 36 + dataSize); d.append("WAVE", 4);
    d.append("fmt ", 4); put32le(d, 16); put16le(d, 1); put16le(d, channels);
    put32le(d, rate); put32le(d, rate * channels * (bps / 8));
    put16le(d, channels * (bps / 8)); put16le(d, bps);
    d.append("data", 4); put32le(d, dataSize);
    d.append(QByteArray(int(dataSize), '\0'));
    QFile f(path);
    if (!f.open(QIODevice::WriteOnly)) return std::string();
    f.write(d);
    f.close();
    return path.toStdString();
}

int main(int argc, char **argv) {
    QCoreApplication app(argc, argv);
    if (argc < 2) {
        std::fprintf(stderr, "usage: %s <MediaInfo.wdx> [ffmpeg-samples-dir]\n", argv[0]);
        return 2;
    }
    void *h = dlopen(argv[1], RTLD_NOW);
    if (!h) {
        std::fprintf(stderr, "dlopen failed: %s\n", dlerror());
        return 2;
    }
    GetField  = reinterpret_cast<GetField_t>(dlsym(h, "ContentGetSupportedField"));
    GetValue  = reinterpret_cast<GetValue_t>(dlsym(h, "ContentGetValue"));
    GetValueW = reinterpret_cast<GetValueW_t>(dlsym(h, "ContentGetValueW"));
    GetDetect = reinterpret_cast<GetDetect_t>(dlsym(h, "ContentGetDetectString"));
    check(GetField && GetValue && GetValueW && GetDetect, "all WDX entry points exported");
    if (!GetField || !GetValue || !GetValueW || !GetDetect) return 2;

    auto setDefaults = reinterpret_cast<void (*)(void *)>(dlsym(h, "ContentSetDefaultParams"));
    auto unloading = reinterpret_cast<void (*)(void)>(dlsym(h, "ContentPluginUnloading"));
    if (setDefaults) setDefaults(nullptr);

    /* Map field names -> indices (decouples the test from enum order). */
    for (int i = 0; i < 256; ++i) {
        char name[128] = {0}, units[128] = {0};
        int t = GetField(i, name, units, sizeof name);
        if (t == 0) break;
        gNames.emplace_back(name);
    }
    check(gNames.size() >= 16, "plugin exposes 17 fields (" + std::to_string(gNames.size()) + ")");
    check(idx("Summary") >= 0 && idx("Dimensions") >= 0 && idx("Page count") >= 0 &&
              idx("Duration (s)") >= 0,
          "core fields present");

    char det[4096] = {0};
    GetDetect(det, sizeof det);
    check(std::strstr(det, "PNG") && std::strstr(det, "PDF") && std::strstr(det, "WAV"),
          "detect string covers image/pdf/audio extensions");

    QTemporaryDir tmp;
    check(tmp.isValid(), "temp dir");
    const QString dir = tmp.path();

    /* ---- image ---- */
    const std::string png = saveImage(dir + "/sample.png", "PNG", 320, 200, 300);
    check(!png.empty(), "PNG written");
    check(getInt(png, "Width") == 320, "PNG Width = 320");
    check(getInt(png, "Height") == 200, "PNG Height = 200");
    std::string s;
    check(getStr(png, "Dimensions", s) && s == "320 \xC3\x97 200",
          "PNG Dimensions = '320 × 200'");
    check(getStr(png, "Summary", s) && s == "320 \xC3\x97 200", "PNG Summary = dims");
    check(std::fabs(getFloat(png, "Megapixels") - 0.1) < 1e-6, "PNG Megapixels = 0.1");
    check(getInt(png, "DPI") == 300, "PNG DPI = 300");
    check(getInt(png, "Bit depth") == 8, "PNG Bit depth = 8");
    check(getInt(png, "Width") != INT32_MIN && getInt(png, "Duration") == INT32_MIN,
          "PNG has no Duration (field empty)");

    const std::string jpg = saveImage(dir + "/sample.jpg", "JPEG", 640, 480, 0);
    check(!jpg.empty(), "JPEG written");
    check(getInt(jpg, "Width") == 640 && getInt(jpg, "Height") == 480, "JPEG 640x480");
    check(getInt(jpg, "Bit depth") == 8, "JPEG Bit depth = 8");

    /* ---- pdf ---- */
    const std::string pdf = makePdf(dir + "/sample.pdf");
    check(!pdf.empty(), "PDF written");
    check(getInt(pdf, "Page count") == 2, "PDF Page count = 2");
    check(getStr(pdf, "Summary", s) && s == "2 pages", "PDF Summary = '2 pages'");
    check(getInt(pdf, "Width") == INT32_MIN, "PDF has no Width");

    /* ---- audio ---- */
    const std::string wav = makeWav(dir + "/sample.wav");
    check(!wav.empty(), "WAV written");
    check(getStr(wav, "Duration", s) && s == "0:01", "WAV Duration = '0:01'");
    check(std::fabs(getFloat(wav, "Duration (s)") - 1.0) < 0.05, "WAV Duration (s) = 1.0");
    check(getInt(wav, "Sample rate") == 8000, "WAV Sample rate = 8000");
    check(getInt(wav, "Channels") == 1, "WAV Channels = 1");
    check(getInt(wav, "Bitrate") == 128, "WAV Bitrate = 128 kbps");
    check(getStr(wav, "Summary", s) && s == "0:01", "WAV Summary = '0:01'");
    check(getInt(wav, "Width") == INT32_MIN, "WAV has no Width");

    /* ---- W (UTF-16) file name, including non-ASCII ---- */
    const QString uni = dir + "/тест.png";
    check(QFile::copy(QString::fromStdString(png), uni), "non-ASCII copy");
    {
        const QString q = uni;
        int32_t w = 0;
        int r = GetValueW(reinterpret_cast<char16_t *>(const_cast<char16_t *>(
                              reinterpret_cast<const char16_t *>(q.utf16()))),
                          idx("Width"), 0, &w, sizeof w, 0);
        check(r == ft_numeric_32 && w == 320, "ContentGetValueW handles UTF-16 paths");
    }

    /* ---- video, when run.sh generated them with ffmpeg ---- */
    auto testVideo = [&](const std::string &path, int w, int h, double dur, double fps,
                         const std::string &vcodec, const std::string &summary) {
        check(getInt(path, "Width") == w && getInt(path, "Height") == h,
              path.substr(path.find_last_of('/') + 1) + " dimensions");
        check(std::fabs(getFloat(path, "Duration (s)") - dur) < 0.25,
              path.substr(path.find_last_of('/') + 1) + " duration");
        check(std::fabs(getFloat(path, "Frame rate") - fps) < 0.1,
              path.substr(path.find_last_of('/') + 1) + " frame rate");
        std::string got, want = vcodec;
        check(getStr(path, "Video codec", got) && got == want,
              path.substr(path.find_last_of('/') + 1) + " video codec = " + want);
        check(getStr(path, "Summary", got) && got == summary,
              path.substr(path.find_last_of('/') + 1) + " summary = '" + summary + "'");
    };
    if (argc >= 3) {
        const QString sd = QString::fromLocal8Bit(argv[2]);
        const std::string avi = (sd + "/sample.avi").toStdString();
        const std::string mkv = (sd + "/sample.mkv").toStdString();
        const std::string mp4 = (sd + "/sample.mp4").toStdString();
        if (QFile::exists(QString::fromStdString(avi)))
            testVideo(avi, 320, 240, 2.0, 25.0, "MPEG-4", "320 \xC3\x97 240 \xC2\xB7 0:02");
        if (QFile::exists(QString::fromStdString(mkv)))
            testVideo(mkv, 640, 480, 1.0, 24.0, "MPEG-4", "640 \xC3\x97 480 \xC2\xB7 0:01");
        if (QFile::exists(QString::fromStdString(mp4))) {
            testVideo(mp4, 480, 270, 1.0, 30.0, "MPEG-4", "480 \xC3\x97 270 \xC2\xB7 0:01");
            check(getStr(mp4, "Audio codec", s) && s == "AAC", "MP4 Audio codec = AAC");
            check(getInt(mp4, "Sample rate") == 44100, "MP4 Sample rate = 44100");
        }
    }

    /* ---- DELAYIFSLOW deferral protocol ---- */
    const std::string wav2 = (dir + "/defer.wav").toStdString();
    check(QFile::copy(QString::fromStdString(wav), QString::fromStdString(wav2)),
          "defer sample copied");
    {
        char buf[64] = {0};
        int r = GetValue(const_cast<char *>(wav2.c_str()), idx("Duration"), 0, buf, sizeof buf,
                         CONTENT_DELAYIFSLOW);
        check(r == ft_delayed, "first DELAYIFSLOW call defers (ft_delayed)");
        check(getStr(wav2, "Duration", s) && s == "0:01",
              "background call (no flag) returns the real value");
    }

    /* ---- robustness ---- */
    {
        int32_t out = 0;
        check(GetValue(const_cast<char *>(png.c_str()), 999, 0, &out, sizeof out, 0) ==
                  ft_nosuchfield,
              "unknown field -> ft_nosuchfield");
        QFile txt(dir + "/notes.txt");
        check(txt.open(QIODevice::WriteOnly), "notes.txt written");
        txt.write("not media\n");
        txt.close();
        const std::string notes = (dir + "/notes.txt").toStdString();
        check(GetValue(const_cast<char *>(notes.c_str()), 0, 0, &out, sizeof out, 0) ==
                  ft_fieldempty,
              "unsupported extension -> ft_fieldempty");
        const std::string missing = (dir + "/missing.mp3").toStdString();
        char buf[64] = {0};
        GetValue(const_cast<char *>(missing.c_str()), idx("Duration"), 0, buf, sizeof buf, 0);
        check(true, "missing file does not crash");
    }

    /* ---- FP traps, as FPC (Double Commander) enables them ---- */
    {
        fesetenv(FE_DFL_ENV);
        feenableexcept(FE_DIVBYZERO | FE_INVALID | FE_OVERFLOW);
        for (int i = 0; i < 3; ++i) {
            const std::string copy = (dir + QString("/trap%1.png").arg(i)).toStdString();
            QFile::copy(QString::fromStdString(png), QString::fromStdString(copy));
            getInt(copy, "Width");
            getStr(copy, "Summary", s);
        }
        check(true, "survived ContentGetValue with FP-exception traps enabled");
        check((fegetexcept() & (FE_DIVBYZERO | FE_INVALID | FE_OVERFLOW)) ==
                  (FE_DIVBYZERO | FE_INVALID | FE_OVERFLOW),
              "plugin restored the host FP-exception environment");
        fedisableexcept(FE_DIVBYZERO | FE_INVALID | FE_OVERFLOW);
    }

    /* ---- concurrency: DC queries columns from worker threads ---- */
    {
        std::vector<std::thread> threads;
        std::vector<int> ok(4, 0);
        for (int t = 0; t < 4; ++t) {
            threads.emplace_back([&, t]() {
                const std::string copy = (dir + QString("/thread%1.wav").arg(t)).toStdString();
                QFile::copy(QString::fromStdString(wav), QString::fromStdString(copy));
                ok[size_t(t)] = getInt(copy, "Sample rate") == 8000;
            });
        }
        for (auto &th : threads) th.join();
        bool all = true;
        for (int v : ok) all = all && v;
        check(all, "concurrent ContentGetValue calls are safe");
    }

    /* ---- version surface ---- */
    check(getStr(png, "Plugin version", s) && s.rfind("MediaInfo ", 0) == 0,
          "Plugin version field present");

    if (unloading) unloading();
    dlclose(h);

    std::printf("\nRESULT: %s  (%d passed, %d failed)\n",
                gFail == 0 ? "PASS" : "FAIL", gPass, gFail);
    return gFail == 0 ? 0 : 1;
}
